    const fetcher=async(url,init)=>{calls.push({url:String(url),init});return String(url).includes("login.microsoftonline.com")?new Response(JSON.stringify({access_token:"opaque-access-token",expires_in:3600}),{status:200,headers:{"Content-Type":"application/json"}}):new Response(null,{status:202});};
