test("complimentary tickets are included in the operational total without generating revenue",()=>{const paid=Array.from({length:98},(_,index)=>exportRow({firstName:`Pagante ${index+1}`,ticketCode:`NIS26-PAID${String(index+1).padStart(3,"0")}`,paymentGroupKey:`order:${index+1}`}));const complimentary=Array.from({length:3},(_,index)=>exportRow({firstName:`Omaggio ${index+1}`,ticketCode:`NIS26-GIFT${String(index+1).padStart(3,"0")}`,source:"ADMIN",invitationType:index===0?"STAMPA":index===1?"MEDIA":"OMAGGIO_NIS",paymentStatus:"NOT_REQUIRED",amount:null,paymentMethod:"Omaggio",paymentState:"NON DOVUTO",collectedAmount:0,outstandingAmount:0,paymentBucket:"NONE",paymentGroupKey:`manual:gift-${index+1}`}));const data=buildParticipantExportDataset([...paid,...complimentary],exportFilters);assert.equal(data.summary.total,101);assert.equal(data.summary.valid,101);assert.equal(data.summary.complimentary,3);assert.equal(data.summary.notDue,3);assert.equal(data.summary.collected,19600);assert.equal(data.rows.length,101);});
