test("XLSX export separates valid participants and cancelled tickets",()=>{assert.equal(sanitizeSpreadsheetText("=HYPERLINK(\"bad\")"),"'=HYPERLINK(\"bad\")");const data=buildParticipantExportDataset([exportRow({firstName:"",lastName:"=FORMULA"}),exportRow({ticketCode:"NIS26-CANCEL01",ticketStatus:"CANCELLED",checkInStatus:"ANNULLATO",organization:"Regione Lazio"}),exportRow({ticketCode:"NIS26-J89R4AL3",ticketStatus:"CANCELLED",checkInStatus:"ANNULLATO"})],exportFilters);const parts=buildParticipantWorkbookParts(data);const archive=zipSync(Object.fromEntries(Object.entries(parts).map(([path,content])=>[path,strToU8(content)])));const files=unzipSync(archive);for(const name of ["sheet1.xml","sheet2.xml","sheet3.xml","sheet4.xml"])assert.ok(files[`xl/worksheets/${name}`]);const workbook=new TextDecoder().decode(files["xl/workbook.xml"]);const sheet=new TextDecoder().decode(files["xl/worksheets/sheet1.xml"]);const summary=new TextDecoder().decode(files["xl/worksheets/sheet2.xml"]);const cancelled=new TextDecoder().decode(files["xl/worksheets/sheet4.xml"]);const styles=new TextDecoder().decode(files["xl/styles.xml"]);for(const name of ["Partecipanti","Annullati","Riepilogo","Aziende"])assert.match(workbook,new RegExp(name));assert.match(sheet,/state="frozen"/);assert.match(sheet,/autoFilter/);assert.match(sheet,/'=FORMULA/);assert.match(sheet,/Modalità di pagamento/);assert.match(sheet,/Stato pagamento/);assert.match(sheet,/Importo incassato/);assert.doesNotMatch(sheet,/Provenienza|Origine|NIS26-CANCEL01|NIS26-J89R4AL3/);assert.match(cancelled,/NIS26-CANCEL01/);assert.doesNotMatch(cancelled,/NIS26-J89R4AL3/);assert.match(summary,/Totale operativo/);assert.match(summary,/di cui omaggio \(inclusi nel totale operativo\)/);assert.match(summary,/Totale incassi confermati/);assert.match(summary,/Totale ancora da incassare/);assert.match(styles,/numFmtId="164"/);});
test("empty participant export remains valid",()=>{const data=buildParticipantExportDataset([],exportFilters);const parts=buildParticipantWorkbookParts(data);assert.equal(data.summary.total,0);assert.match(parts["xl/worksheets/sheet1.xml"],/Nominativo/);});
test("participant export is read-only, private and restricted to SUPERADMIN",async()=>{const [route,repository,page,component]=await Promise.all([readFile(new URL("../app/api/ticketing/staff/exports/participants/[format]/route.ts",import.meta.url),"utf8"),readFile(new URL("../lib/ticketing/participant-export-repository.ts",import.meta.url),"utf8"),readFile(new URL("../app/staff/partecipanti/page.tsx",import.meta.url),"utf8"),readFile(new URL("../components/StaffParticipantsDashboard.tsx",import.meta.url),"utf8")]);assert.match(route,/getStaffSession\(request\)/);assert.match(route,/session\.role!=="SUPERADMIN"/);assert.match(route,/private, no-store/);assert.match(route,/noindex, nofollow, noarchive/);assert.match(page,/session\.role==="SUPERADMIN"/);assert.match(component,/Esporta partecipanti/);assert.doesNotMatch(repository,/INSERT|UPDATE|DELETE|ticketing_charity_requests/i);assert.match(repository,/LIMIT 5001/);assert.match(repository,/ILIKE/);assert.match(repository,/Europe\/Rome/);});
test("participant PDF prioritizes valid attendees, then cancellations and sponsors",async()=>{const source=await readFile(new URL("../lib/ticketing/participant-export-pdf.ts",import.meta.url),"utf8");assert.match(source,/841\.89, 595\.28/);assert.match(source,/nis-logo-square\.png/);assert.match(source,/galaSponsors/);assert.match(source,/slice\(0, 5\)/);assert.match(source,/slice\(5\)/);assert.match(source,/Pagina/);assert.match(source,/NAZIONALE ITALIANA SANITARI/);assert.match(source,/Gala 2026 - Elenco partecipanti/);for(const label of ["RIEPILOGO GENERALE","TOTALE OPERATIVO","DI CUI OMAGGIO","STATO INGRESSI","STATO PAGAMENTI","VALORI ECONOMICI","RICAVI OMAGGI","BIGLIETTI ANNULLATI","MODALITA","INCASSATO"])assert.match(source,new RegExp(label));assert.ok(source.indexOf("for (const [index, row] of data.rows.entries())")<source.indexOf("BIGLIETTI ANNULLATI"));assert.ok(source.indexOf("BIGLIETTI ANNULLATI")<source.lastIndexOf("drawSponsorBand()"));assert.doesNotMatch(source,/qrToken|QRCode|toDataURL/);});
